import{_ as i,l as n,o as e,c as s,v as t,p as l,x as r,d as p,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"前景理论资产定价","description":"","frontmatter":{"title":"前景理论资产定价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/prospect-theory-asset-pricing.md","filePath":"econ/prospect-theory-asset-pricing.md","lastUpdated":1789023840000}'),d={name:"econ/prospect-theory-asset-pricing.md"};function m(h,a,B,A,u,_){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="前景理论资产定价" tabindex="-1">前景理论资产定价 <a class="header-anchor" href="#前景理论资产定价" aria-label="Permalink to &quot;前景理论资产定价&quot;">​</a></h1><div class="epigraph"><p>若股票被窄框架评价，且一年看一次，损失厌恶足以要很高的股权溢价——不必把 $\\gamma$ 顶到两位数。</p><footer>—— Benartzi and Thaler, Myopic Loss Aversion and the Equity Premium Puzzle, QJE 1995；Barberis, Huang and Santos, QJE 2001</footer></div><p><a href="/econ/hong-stein-diffusion">上一课</a>走信念。本课缺口是评价：把<a href="/econ/prospect-theory">前景理论</a>与<a href="/econ/mental-accounting">心理账户</a>接到资产价格，对照<a href="/econ/equity-premium-puzzle">股权溢价之谜</a>。不重推 Mehra–Prescott 的校准，不重导 vNM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代表性 CRRA 用平滑的总量 \\(c\\) 生成 \\(m\\)，溢价要极大 \\(\\gamma\\)。Benartzi 与 Thaler（1995）：投资者用前景理论评价股票的<strong>名义收益分布</strong>，评价频率约一年（窄框架，不并入总财富）。损失厌恶使一年期股票的价值函数期望为负，除非溢价大到把分布抬离损失区。Barberis、Huang 与 Santos（2001）把它动态化：过去收益改变下一期的损失厌恶或参考点，波动与可预测性同时出现。Barberis 与 Huang（2008）用 CPT 的概率加权给彩票型股票定价：正偏被高估，平均收益可以低。</p><p>缺口是改 \\(v\\) 与框架，而不是再改消费过程。</p><p><span class="marginnote">短视损失厌恶：同一长期风险，看的次数越多，碰到损失的次数越多，\\(\\lambda\\) 打击越多。评价频率是偏好的一部分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把资产的收益分布送进 \\(v\\) 与 \\(w\\)，而不是送进 \\(\\mathbb{E}u(c)\\)。静态 BT 用历史年收益直方图。BHS 用均衡消费加前瞻性损失厌恶状态变量。本课不把习惯形成（Campbell–Cochrane）重写一遍：习惯改 \\(u(c-X)\\)，前景改金融财富的得失，可以并存，对象不同。</p>',9)),(e(),l(E,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EPP%5B%22%E6%BA%A2%E4%BB%B7%E4%B9%8B%E8%B0%9C%3A%20%E6%80%BB%E9%87%8F%20c%20%E5%A4%AA%E5%B9%B3%22%5D%20--%3E%20MLA%5B%22%E7%AA%84%E6%A1%86%E6%9E%B6%20%2B%20%E6%8D%9F%E5%A4%B1%E5%8E%8C%E6%81%B6%20%2B%20%E5%B9%B4%E9%A2%91%22%5D%0A%20%20MLA%20--%3E%20PREM%5B%22%E4%B8%8D%E5%BF%85%E6%9E%81%E5%A4%A7%20gamma%22%5D%0A%20%20CPT%5B%22%E6%A6%82%E7%8E%87%E5%8A%A0%E6%9D%83%22%5D%20--%3E%20LOTT%5B%22%E5%BD%A9%E7%A5%A8%E5%9E%8B%3A%20%E9%AB%98%E5%81%8F%E5%BA%A6%2C%20%E4%BD%8E%E5%B9%B3%E5%9D%87%E6%94%B6%E7%9B%8A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是金融财富被单独记账。欧拉若仍对总消费成立，股票收益的得失另加一项前景效用，有效风险价格上升。这与参与之谜一致：窄框架使一次公平的股权赌注看起来很糟，零持有增加。套利限制仍然需要：若有不受窄框架约束的机构，他们应吃掉溢价——除非委托与基准也迫使他们短视。</p><p>不把溢价写成盘口价差。本课 \\(p\\) 仍是均衡价格。</p><p>Mehra–Prescott 的缺口是 \\(\\sigma(\\Delta c)\\) 太小。BT 不改消费过程，改评价对象：一年期名义股票收益的直方图进 \\(v\\)，损失区被 \\(\\lambda\\) 放大，没有足够溢价则价值为负。评价频率是窄框架的结算规则，与心理账户同一零件。BHS 让过去收益进入下期损失厌恶，波动与可预测性跟着状态走，仍不必两位数 \\(\\gamma\\)。习惯形成改的是 \\(c-X\\)，对象是消费；本课对象是金融财富账户。机构若也不并入总财富（基准、年考核），套利吃不掉溢价。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>评价频率是自由参数；改成每天或十年，溢价预测大变。BT 用历史分布，不是一般均衡。BHS 更接近均衡，但对 \\(v\\) 的动态有额外假设。本课不宣称前景理论「解决」了谜，只标明一条不靠两位数 \\(\\gamma\\) 的通道。量化栏的因子实证不在此重做。</p><p>后课默认：处置效应是同一 \\(v\\) 在交易实现上的含义，不是定价核的再校准。</p><p>不改 \\(\\sigma(\\Delta c)\\)，改评价对象：一年期名义收益进 \\(v\\)，窄框架让 \\(\\lambda\\) 要很高溢价。</p><p>习惯改 \\(c-X\\)，本课改金融财富账户。机构年考核也可以是短视。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>短视损失厌恶用窄框架解释高溢价，不重推 HJ 界。</li><li>CPT 加权给正偏证券低期望收益。</li><li>与习惯分工：一个改消费效用，一个改金融财富得失。</li><li>评价频率是自由参数，必须声明。</li><li>CPT 加权给正偏彩票型低期望收益。</li><li>出处：Benartzi and Thaler, <em>QJE</em> 1995；Barberis, Huang and Santos, <em>QJE</em> 2001。</li></ul>',11))])}const g=i(d,[["render",m]]);export{f as __pageData,g as default};
